import '../data/repo.dart';

// Translation order in each list: Tamil, Hindi, Telugu, Malayalam, Kannada.
const _order = {'Tamil': 0, 'Hindi': 1, 'Telugu': 2, 'Malayalam': 3, 'Kannada': 4};

/// Translates an English UI string into the language chosen on the Language screen.
/// Falls back to English when no translation exists. Recipe data stays in English.
String t(String s) {
  final i = _order[Repo.i.language];
  if (i == null) return s;
  final l = _tr[s];
  return (l == null || l.length <= i || l[i].isEmpty) ? s : l[i];
}

/// Translation with {placeholders}.
String tf(String s, Map<String, String> args) {
  var out = t(s);
  args.forEach((k, v) => out = out.replaceAll('{$k}', v));
  return out;
}

String? _lookup(String key) {
  final i = _order[Repo.i.language];
  if (i == null) return null;
  final l = _tr[key];
  return (l == null || l.length <= i || l[i].isEmpty) ? null : l[i];
}

/// Translates a measuring unit (cup, teaspoon, clove ...). Unknown units stay as they are.
String tUnit(String u) {
  final l = u.toLowerCase().trim();
  if (l.isEmpty) return u;
  for (final k in [l, if (l.endsWith('es')) l.substring(0, l.length - 2), if (l.endsWith('s')) l.substring(0, l.length - 1)]) {
    final r = _lookup('u:$k');
    if (r != null) return r;
  }
  return u;
}

/// Dictionary translation of an ingredient name, or null when the word list does not know it.
String? tIngKnown(String name) {
  if (Repo.i.language == 'English') return null;
  var n = name.toLowerCase().replaceAll(RegExp(r'\([^)]*\)'), ' ').replaceAll(RegExp(r'[^a-z ]'), ' ').replaceAll(RegExp(r'\s+'), ' ').trim();
  if (n.isEmpty) return null;
  final bases = <String>{n};
  for (final p in ['fresh ', 'dried ', 'dry ', 'whole ', 'chopped ', 'boiled ', 'roasted ', 'raw ', 'ripe ']) {
    if (n.startsWith(p)) bases.add(n.substring(p.length));
  }
  for (final b in bases.toList()) {
    bases.add(b.endsWith('ies') ? '${b.substring(0, b.length - 3)}y' : b);
    if (b.endsWith('es')) bases.add(b.substring(0, b.length - 2));
    if (b.endsWith('s')) bases.add(b.substring(0, b.length - 1));
  }
  for (final b in bases) {
    final r = _lookup('i:$b') ?? _lookup(b);
    if (r != null) return r;
  }
  return null;
}

